// JAH demo program — The filter
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function filter3(compounds, survives, universal){ var n=(compounds?1:0)+(survives?1:0)+(universal?1:0);
  return n===3?'rare and precious — do it':n===2?'promising — check the gap':'pass'; }
check("3/3", filter3(true,true,true), "rare and precious \u2014 do it");
check("2/3", filter3(true,true,false), "promising \u2014 check the gap");
check("1/3", filter3(true,false,false), "pass");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

